begin;
create temporary table assertions(label text);
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin
 if value is distinct from true then raise exception 'Reader resource assertion failed: %',label;end if;insert into assertions values(label);end$$;
do $$declare x jsonb;f uuid;r uuid;rr integer;a timestamptz;b timestamptz;o jsonb;borrow uuid;transfer uuid;legacy uuid;zone text;begin
 x:=mp_test.fixture('calendar-reader');f:=(x->>'factory')::uuid;r:=(x->>'request')::uuid;
 select revision into rr from public.maintenance_requests where id=r;select timezone into zone from public.factories where id=f;
 a:=(((clock_timestamp()+interval '2 days') at time zone zone)::date+'09:30'::time) at time zone zone;
 perform public.configure_working_calendar(f,127,'09:00','10:00');
 perform public.plan_product_item(f,(x->>'item')::uuid,(x->>'line')::uuid,a);
 select expected_finish into b from public.production_orders where id=(x->>'item')::uuid;
 perform pg_temp.ok((b at time zone zone)::time='09:35' and (b at time zone zone)::date=(a at time zone zone)::date+1,'production finish includes setup and closed calendar time');
 perform pg_temp.ok(public.maintenance_planning_preview(f,r,a+interval '2 hours',a+interval '3 hours',rr,0)->>'capacity'='BLOCKED','stored production interval protects closed-time span');
 perform pg_temp.ok(public.maintenance_planning_preview(f,r,b,b+interval '1 hour',rr,0)->>'capacity'='CLEAR','calendar/setup exact finish boundary');
 o:=public.maintenance_planning_gaps(f,r,b,b+interval '1 day',rr,0,60);
 perform pg_temp.ok((o->'suggestions'->0->>'end')::timestamptz-(o->'suggestions'->0->>'start')::timestamptz=interval '1 hour','maintenance duration continuous across production calendar');
 legacy:=public.create_maintenance_request(f,jsonb_build_object('work_center_id',x->>'machine','title','Legacy unknown duration','priority','NORMAL','separate_problem',true),gen_random_uuid());
 select revision into rr from public.maintenance_requests where id=legacy;
 perform pg_temp.ok(public.maintenance_planning_preview(f,legacy,b,b+interval '1 hour',rr,0)->>'capacity'='UNKNOWN','missing legacy duration remains unknown');
 perform pg_temp.ok(public.maintenance_planning_preview(f,legacy,b,null,rr,0)->'end'='null'::jsonb,'unknown duration does not fabricate a default end');
 x:=mp_test.fixture('transfer-reader');f:=(x->>'factory')::uuid;r:=(x->>'request')::uuid;
 select revision into rr from public.maintenance_requests where id=r;a:=clock_timestamp()+interval '2 days';b:=a+interval '1 hour';
 perform public.configure_center_capabilities(f,(x->>'independent')::uuid,jsonb_build_array(jsonb_build_object('product_id',x->>'product','rate',100,'rate_unit','meter','setup_minutes',5)));
 perform public.configure_center_alternatives(f,(x->>'machine')::uuid,array[(x->>'independent')::uuid]);
 update public.work_centers set dependency_mode='buffer',buffer_minutes=30 where id=(x->>'machine')::uuid;
 o:=public.maintenance_planning_preview(f,r,a,b,rr,0);
 perform pg_temp.ok(o->'scope'->>'buffer_credit'='false' and o->'scope'->>'alternative_credit'='false' and o->'scope'->>'kind'='WHOLE_LINE','buffer/alternative configuration grants no speculative capacity');
 perform public.plan_product_item(f,(x->>'item')::uuid,(x->>'line')::uuid,a);
 perform public.start_product_item(f,(x->>'item')::uuid);
 o:=public.maintenance_planning_preview(f,r,b,b+interval '1 hour',rr,0);
 perform pg_temp.ok(o->>'capacity'='BLOCKED','active production has no assumed historical planned release');
 perform public.stop_machine(f,(x->>'machine')::uuid,'planned',null,'inspection','Local transfer setup');
 transfer:=public.transfer_production(f,(x->>'machine')::uuid,(x->>'independent')::uuid,'Local reader ownership');
 o:=public.maintenance_planning_preview(f,r,a,b,rr,0);
 perform pg_temp.ok(o->'conditions'->>'open_transfer'='true' and o->>'capacity'='BLOCKED','OPEN original ownership blocks candidate');
 borrow:=public.create_maintenance_request(f,jsonb_build_object('work_center_id',x->>'independent','title','Borrower preview','priority','NORMAL','maintenance_kind','PLANNED','estimated_duration_minutes',1),gen_random_uuid());
 select revision into rr from public.maintenance_requests where id=borrow;
 o:=public.maintenance_planning_preview(f,borrow,a,b,rr,0);
 perform pg_temp.ok(o->'conditions'->>'open_transfer'='true' and o->>'capacity'='BLOCKED','OPEN borrower and competing assignment protected');
 perform pg_temp.ok(public.maintenance_planning_gaps(f,borrow,a,a+interval '1 day',rr,0)->'suggestions'='[]','no free gap through OPEN transfer');
 perform pg_temp.ok((select ended_at is null from public.production_transfers where id=transfer),'reader never ends actual transfer');
 perform pg_temp.ok(not (select enabled from private.maintenance_planning_activation),'resource readers never activate gate');
end$$;
select 'PASS '||label from assertions;
rollback;
